mapper.select:
SELECT COALESCE(SUM(bounty_amount), 0)
FROM merchant_referral_bounty
WHERE inviter_member_id = #{inviterMemberId}
  AND status = 1
  AND frozen_until > #{now}
  AND del_flag = '0'

SELECT COUNT(DISTINCT r.member_id)
FROM cms_registration r
WHERE r.payment_status = 2
  AND r.registration_status <> 3
  AND EXISTS (
    SELECT 1 FROM cms_registration_scan s
    WHERE s.registration_id = r.id
      AND s.member_id = #{merchantMemberId}
      AND s.registration_type = 1
      AND s.create_time >= #{windowStart}
      AND s.create_time < #{windowEnd}
  )

SELECT COALESCE(SUM(COALESCE(r.payable_amount, 0)), 0)
FROM cms_registration r
WHERE r.payment_status = 2
  AND r.registration_status <> 3
  AND EXISTS (
    SELECT 1 FROM cms_registration_scan s
    WHERE s.registration_id = r.id
      AND s.member_id = #{merchantMemberId}
      AND s.registration_type = 1
      AND s.create_time >= #{windowStart}
      AND s.create_time < #{windowEnd}
  )

SELECT MIN(r.id)
FROM cms_registration r
WHERE r.payment_status = 2
  AND r.registration_status <> 3
  AND EXISTS (
    SELECT 1 FROM cms_registration_scan s
    WHERE s.registration_id = r.id
      AND s.member_id = #{merchantMemberId}
      AND s.registration_type = 1
      AND s.create_time >= #{windowStart}
      AND s.create_time < #{windowEnd}
  )
GROUP BY r.member_id
ORDER BY MIN(r.id) ASC
LIMIT #{limit}

SELECT COUNT(*) FROM cms_registration r WHERE r.id IN
#{rid}
AND r.payment_status = 2 AND r.registration_status <> 3 AND EXISTS ( SELECT 1 FROM cms_registration_scan s WHERE s.registration_id = r.id AND s.member_id = #{merchantMemberId} AND s.registration_type = 1 )
